powerpagecomponent.content:
{
  "source": "{%- assign ctaText = ctaLabel | default: 'View Program' -%}
{%- assign targetAttributes = targetAttrs | default: targetAttr | default: '' -%}

{%- comment -%}
Featured card that matches existing CSS selectors:
- .hit-card__inner--featured (aspect ratio + background image)
- .hit-card__overlay
- .hit-card__body--featured
- .hit-card__title--featured
- .hit-card__summary--featured
- .hit-card__stretchedLink (z-index safety rules)
{%- endcomment -%}

{%- assign bgStyle = '' -%}
{%- if imageUrl and imageUrl != '' -%}
  {%- assign bgStyle = 'background-image:url(' | append: imageUrl | append: ');' -%}
{%- endif -%}

<article class="hit-card hit-card--minimal">
  <div class="hit-card__inner hit-card__inner--minimal">

    {%- if href and href != '' -%}
      <a class="hit-card__stretchedLink"
         href="{{ href | escape_once }}"{{ targetAttributes }}
         aria-label="{{ title | escape }}">
      </a>
    {%- endif -%}

    {%- if imageUrl and imageUrl != '' -%}
      <div class="hit-card__media hit-card__media--minimal">
        <img class="hit-card__image hit-card__image--minimal"
             src="{{ imageUrl | escape }}"
             alt="{{ title | escape }}">
      </div>
    {%- endif -%}

    <div class="hit-card__body hit-card__body--minimal">
      {%- if href and href != '' -%}
        <h3 class="hit-card__title hit-card__title--minimal">
          <a class="hit-card__titleLink"
             href="{{ href | escape_once }}"{{ targetAttributes }}>
            {{ title | escape }}
          </a>
        </h3>
      {%- else -%}
        <h3 class="hit-card__title hit-card__title--minimal">
          {{ title | escape }}
        </h3>
      {%- endif -%}
    </div>
  </div>
</article>"
}
